fun validateTrip(origin: String, destination: String) = origin.isNotBlank() && destination.isNotBlank() && !origin.trim().equals(destination.trim(), true)

data class Route(val name: String, val duration: String, val distance: String, val score: String, val note: String)
data class Report(val category: String, val severity: String, val description: String, val status: String = "Submitted")

class AppViewModel : ViewModel() {
    var route by mutableStateOf("splash"); private set
    var origin by mutableStateOf("Current location"); var destination by mutableStateOf("")
    var context by mutableStateOf("General Travel"); var darkMode by mutableStateOf(false); var largeText by mutableStateOf(false)
    var voiceGuidance by mutableStateOf(true); var offline by mutableStateOf(false); var selectedRoute by mutableStateOf(0)
    var report by mutableStateOf<Report?>(null); var reportDraft by mutableStateOf(Report("Pothole", "Medium", ""))
    var savedPlaces = mutableStateListOf("Home · 12 Lake View Road", "Office · 44 MG Road")
    val routes = listOf(Route("Balanced route", "28 min", "12.4 km", "4.6/5", "Good road surface · light traffic"), Route("Safest route", "34 min", "13.8 km", "4.9/5", "Well-lit roads · low hazard history"), Route("Express route", "22 min", "11.2 km", "3.8/5", "Construction ahead · use caution"))
    val pois = listOf("City Museum · Attraction · 1.8 km", "Sri Lakshmi Temple · Temple · 2.4 km", "Central Emergency Hospital · Emergency · 3.1 km")
    fun go(to: String) { route = to }
    fun startTrip() { if (validateTrip(origin, destination)) go("routes") }
    fun submitReport() { report = reportDraft; go("reportDetails") }
}

private val Blue = Color(0xFF1769E0); private val Ink = Color(0xFF14213D); private val Surface = Color(0xFFF7F9FC)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { ContextRouteApp() } }
}

@Composable fun ContextRouteApp(vm: AppViewModel = viewModel()) {
    MaterialTheme(colorScheme = if (vm.darkMode) darkColorScheme(primary = Color(0xFF9CC3FF)) else lightColorScheme(primary = Blue, background = Surface)) {
        Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
            ScreenHost(vm)
        }
    }
}

@Composable private fun ScreenHost(vm: AppViewModel) {
    val onboarding = vm.route.startsWith("onboard") || vm.route == "splash" || vm.route == "permission"
    Scaffold(bottomBar = { if (!onboarding && vm.route !in listOf("navigation", "emergency")) BottomBar(vm) }) { pad ->
        Box(Modifier.padding(pad)) { when (vm.route) {
            "splash" -> Splash(vm); "onboard1" -> Onboard(vm, 1, "Smarter routes", "Recommendations that adapt to your purpose, preferences and the road ahead.", Icons.Default.Route)
            "onboard2" -> Onboard(vm, 2, "Your journey, your context", "Choose family, work, tourism, medical or religious travel and get a route that fits.", Icons.Default.Explore)
            "onboard3" -> Onboard(vm, 3, "Safety and accessibility first", "See road conditions, hazards and accessible choices before you start moving.", Icons.Default.Shield)
            "permission" -> PermissionScreen(vm); "home" -> Home(vm); "search" -> Search(vm); "context" -> ContextScreen(vm); "requirements" -> Requirements(vm)
            "routes" -> Routes(vm); "overview" -> Overview(vm); "navigation" -> NavigationScreen(vm); "explore" -> Explore(vm); "report" -> ReportForm(vm); "reportDetails" -> ReportDetails(vm); "lifecycle" -> Lifecycle(vm)
            "emergency" -> Emergency(vm); "saved" -> Saved(vm); "profile" -> Profile(vm); "offline" -> Offline(vm); "privacy" -> Privacy(vm); "settings" -> Settings(vm)
            else -> Home(vm)
        } }
    }
}

@Composable private fun BottomBar(vm: AppViewModel) { NavigationBar { listOf("home" to Icons.Default.Home, "explore" to Icons.Default.Explore, "saved" to Icons.Default.Bookmark, "profile" to Icons.Default.Person).forEach { (r, icon) -> NavigationBarItem(selected = vm.route == r, onClick = { vm.go(r) }, icon = { Icon(icon, null) }, label = { Text(r.replaceFirstChar { it.uppercase() }) }) } } }

@Composable private fun Header(title: String, vm: AppViewModel, back: Boolean = true, action: (@Composable () -> Unit)? = null) { Row(Modifier.fillMaxWidth().padding(horizontal = 20.dp, vertical = 14.dp), verticalAlignment = Alignment.CenterVertically) { if (back) IconButton({ vm.go("home") }, Modifier.semantics { contentDescription = "Go back" }) { Icon(Icons.Default.ArrowBack, null) }; Text(title, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, modifier = Modifier.weight(1f)); action?.invoke() } }
@Composable private fun Page(title: String, vm: AppViewModel, body: @Composable ColumnScope.() -> Unit) { LazyColumn(Modifier.fillMaxSize().padding(horizontal = 20.dp), contentPadding = PaddingValues(bottom = 28.dp)) { item { Header(title, vm) }; item { body() } } }
@Composable private fun CardBox(modifier: Modifier = Modifier, content: @Composable ColumnScope.() -> Unit) { Card(modifier.fillMaxWidth().padding(vertical = 6.dp), shape = RoundedCornerShape(18.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)) { Column(Modifier.padding(16.dp), content = content) } }
@Composable private fun Primary(text: String, onClick: () -> Unit, modifier: Modifier = Modifier) { Button(onClick, modifier.fillMaxWidth().heightIn(min = 52.dp), shape = RoundedCornerShape(14.dp)) { Text(text, fontWeight = FontWeight.SemiBold) } }
