@Composable private fun MapPlaceholder(label: String = "Demo map · no live GPS or map provider configured") { Box(Modifier.fillMaxWidth().height(230.dp).clip(RoundedCornerShape(22.dp)).background(Color(0xFFDCEBFA)), contentAlignment = Alignment.Center) { Column(horizontalAlignment = Alignment.CenterHorizontally) { Icon(Icons.Default.Map, null, tint = Blue, modifier = Modifier.size(48.dp)); Text(label, color = Ink, fontSize = 13.sp); Text("Route preview", color = Blue, fontWeight = FontWeight.Bold) } } }

@Composable private fun Splash(vm: AppViewModel) { Column(Modifier.fillMaxSize().padding(28.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.Center) { Box(Modifier.size(104.dp).clip(CircleShape).background(Blue), contentAlignment = Alignment.Center) { Icon(Icons.Default.Navigation, null, tint = Color.White, modifier = Modifier.size(58.dp)) }; Spacer(Modifier.height(24.dp)); Text("ContextRoute AI", fontSize = 31.sp, fontWeight = FontWeight.Bold, color = Ink); Text("Personalized. Safer. Smarter Travel.", color = Color.Gray); Spacer(Modifier.height(50.dp)); Primary("Get started") { vm.go("onboard1") }; TextButton({ vm.go("home") }) { Text("Skip onboarding") } } }
@Composable private fun Onboard(vm: AppViewModel, page: Int, title: String, desc: String, icon: androidx.compose.ui.graphics.vector.ImageVector) { Column(Modifier.fillMaxSize().padding(28.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.Center) { Box(Modifier.size(190.dp).clip(RoundedCornerShape(44.dp)).background(Color(0xFFE4EEFF)), contentAlignment = Alignment.Center) { Icon(icon, null, tint = Blue, modifier = Modifier.size(96.dp)) }; Spacer(Modifier.height(30.dp)); Text(title, fontSize = 28.sp, fontWeight = FontWeight.Bold, color = Ink); Text(desc, fontSize = 17.sp, color = Color.Gray, modifier = Modifier.padding(top = 12.dp), textAlign = androidx.compose.ui.text.style.TextAlign.Center); Spacer(Modifier.height(30.dp)); Text("●  ".repeat(page) + "○  ".repeat(3 - page), color = Blue); Spacer(Modifier.height(30.dp)); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { TextButton({ vm.go("home") }) { Text("Skip") }; Button({ if (page < 3) vm.go("onboard${page + 1}") else vm.go("permission") }) { Text(if (page < 3) "Next" else "Get started") } } } }

@Composable private fun PermissionScreen(vm: AppViewModel) { val context = LocalContext.current; val launcher = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { vm.go("home") }; Page("Set up your permissions", vm) { Text("ContextRoute works best with a few optional Android permissions.", style = MaterialTheme.typography.bodyLarge); listOf("Location" to "Show your position and find nearby facilities", "Notifications" to "Keep you informed about saved trip updates", "Camera / photos" to "Attach an image to a road report (optional)").forEach { (a,b) -> CardBox { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.CheckCircle, null, tint = Blue); Spacer(Modifier.width(12.dp)); Column { Text(a, fontWeight = FontWeight.Bold); Text(b, color = Color.Gray) } } } }; Spacer(Modifier.height(12.dp)); Primary("Continue") { launcher.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION, Manifest.permission.POST_NOTIFICATIONS)) }; TextButton({ vm.go("home") }, Modifier.fillMaxWidth()) { Text("Not now") }; Text("Permissions can be changed later in Android Settings. We never imply a permission was granted when it was denied.", color = Color.Gray, fontSize = 12.sp) } }

@Composable private fun Home(vm: AppViewModel) { LazyColumn(Modifier.fillMaxSize().padding(horizontal = 20.dp), contentPadding = PaddingValues(bottom = 24.dp)) { item { Row(Modifier.padding(top = 20.dp), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("Good morning", color = Color.Gray); Text("Where to today?", style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Bold, color = Ink) }; IconButton({ vm.go("emergency") }) { Icon(Icons.Default.Emergency, "Emergency", tint = Color.Red) } } }; item { if (vm.offline) DemoBanner("Offline mode · showing cached demo data") else DemoBanner() }; item { MapPlaceholder() }; item { Spacer(Modifier.height(14.dp)); OutlinedButton({ vm.go("search") }, Modifier.fillMaxWidth().height(56.dp), shape = RoundedCornerShape(14.dp)) { Icon(Icons.Default.Search, null); Spacer(Modifier.width(8.dp)); Text("Plan a route") } }; item { Text("Quick access", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 22.dp)) }; item { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { Quick("Explore", Icons.Default.Explore) { vm.go("explore") }; Quick("Report", Icons.Default.ReportProblem) { vm.go("report") }; Quick("Saved", Icons.Default.Bookmark) { vm.go("saved") } } }; item { Text("Recent places", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 22.dp)); CardBox { Text("No live trip history", color = Color.Gray); Text("Your locally saved places will appear here.", fontSize = 13.sp, color = Color.Gray) } } } }
