@Composable private fun ReportForm(vm: AppViewModel) { var desc by remember { mutableStateOf(vm.reportDraft.description) }; Page("Report a road issue", vm) { DemoBanner("Reports are saved locally and marked pending sync when offline."); Text("Hazard category", fontWeight = FontWeight.Bold); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) { listOf("Pothole", "Damaged road", "Waterlogging").forEach { AssistChip({ vm.reportDraft = vm.reportDraft.copy(category = it) }, label = { Text(it) }) } }; Text("Severity", fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 14.dp)); Row { listOf("Low", "Medium", "High").forEach { FilterChip(vm.reportDraft.severity == it, { vm.reportDraft = vm.reportDraft.copy(severity = it) }, label = { Text(it) }, modifier = Modifier.padding(end = 6.dp)) } }; OutlinedTextField(desc, { if (it.length <= 250) { desc = it; vm.reportDraft = vm.reportDraft.copy(description = it) } }, Modifier.fillMaxWidth().padding(top = 12.dp), label = { Text("Description (optional, 250 characters)") }, minLines = 3); Text("Location: demo coordinates unavailable", color = Color.Gray, fontSize = 13.sp); Spacer(Modifier.height(14.dp)); Primary("Submit report") { vm.submitReport() } } }
